"""Optional notebook structure, environment, and fresh-kernel execution contract."""

import hashlib
import json
import math
import os
import re
import sys
import tempfile
import tomllib
from dataclasses import dataclass
from importlib import import_module
from importlib.metadata import version
from pathlib import Path
from typing import TYPE_CHECKING, Literal

from research_repo_tools import files, toolchain, toolchain_config
from research_repo_tools.config import Config
from research_repo_tools.process import run_safe_command

if TYPE_CHECKING:
    from nbformat import NotebookNode

KERNEL = "research-repo-tools"
CELL_ID = re.compile(r"[A-Za-z0-9_-]{1,64}")


def dependency(name: str):
    try:
        return import_module(name)
    except ImportError as error:
        raise RuntimeError(
            f"Notebook dependency {name!r} is unavailable; declare research-repo-tools[notebooks] in the notebook dependency group and run notebooks sync."
        ) from error


@dataclass(frozen=True)
class Notebook:
    path: Path
    original: bytes
    node: NotebookNode


def _object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON key")
        result[key] = value
    return result


def _constant(_value: str):
    raise ValueError("non-finite JSON number")


def _finite_float(value: str) -> float:
    result = float(value)
    if not math.isfinite(result):
        _constant(value)
    return result


def _check_unicode(raw: object) -> None:
    pending = [raw]
    while pending:
        value = pending.pop()
        if isinstance(value, str):
            if re.search(r"[\ud800-\udfff]", value):
                raise ValueError("unpaired Unicode surrogate in notebook JSON")
        elif isinstance(value, dict):
            pending.extend(value)
            pending.extend(value.values())
        elif isinstance(value, list):
            pending.extend(value)


def read_raw(path: Path) -> tuple[bytes, dict]:
    """Read unambiguous JSON without conversion, normalization, or ID generation."""
    original = path.read_bytes()
    try:
        raw = json.loads(original.decode("utf-8"), object_pairs_hook=_object, parse_constant=_constant, parse_float=_finite_float)
        _check_unicode(raw)
        if not isinstance(raw, dict) or type(raw.get("nbformat")) is not int or raw["nbformat"] != 4:
            raise ValueError("expected nbformat 4")
        if not isinstance(raw.get("cells"), list):
            raise ValueError("cells must be an array")
        return original, raw
    except (ValueError, UnicodeError) as error:
        raise ValueError(f"{path}: {error}") from error


def load(path: Path) -> Notebook:
    """Validate without nbformat's implicit ID repair or version conversion."""
    nbformat = dependency("nbformat")
    original, raw = read_raw(path)
    try:
        if type(raw.get("nbformat_minor")) is not int or raw["nbformat_minor"] != 5:
            raise ValueError("expected nbformat 4.5 with stable cell IDs")
        cells = raw.get("cells")
        if not isinstance(cells, list):
            raise ValueError("cells must be an array")
        seen: set[str] = set()
        for index, cell in enumerate(cells, 1):
            if not isinstance(cell, dict) or not isinstance(cell_id := cell.get("id"), str) or CELL_ID.fullmatch(cell_id) is None:
                raise ValueError(f"cell {index}: expected an existing 1-64 character ASCII cell ID")
            if cell_id in seen:
                raise ValueError(f"cell {index}: duplicate cell ID {cell_id!r}")
            seen.add(cell_id)
        # The schema validator, unlike reads()/validate(), never normalizes IDs.
        validator = nbformat.validator.get_validator(version=4, version_minor=5)
        if validator is None:
            raise RuntimeError("nbformat 4.5 validator is unavailable")
        try:
            validator.validate(raw)
        except nbformat.ValidationError as error:
            raise ValueError(f"invalid notebook structure: {error.message}") from error
        # Stored notebooks may encode multiline sources/output text as lists.
        # Decode those representations only after strict validation has ruled
        # out ID repair, schema conversion, and malformed source state.
        return Notebook(path.resolve(), original, nbformat.reads(original.decode("utf-8"), as_version=4))
    except (ValueError, UnicodeError) as error:
        raise ValueError(f"{path}: {error}") from error

"""Explicit benchmark release selection, independent of measurement and I/O."""

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Literal

from research_repo_tools.release_discovery import PublishedRelease, _tag_version, normalize_tag

type PairMode = Literal["explicit", "published-latest", "infer-release", "current-vs-latest"]
type ReleaseOrder = Literal["published", "version"]

__all__ = ["PairMode", "ReleaseOrder", "ReleasePair", "resolve_pair"]


@dataclass(frozen=True, slots=True)
class ReleasePair:
    current: str
    baseline: str

    def __post_init__(self) -> None:
        for name in ("current", "baseline"):
            object.__setattr__(self, name, normalize_tag(getattr(self, name)))

    @property
    def stem(self) -> str:
        return f"{self.current}-vs-{self.baseline}"


def resolve_pair(
    mode: PairMode,
    *,
    package_tag: str,
    releases: Sequence[PublishedRelease] = (),
    order: ReleaseOrder = "published",
    current: str | None = None,
    baseline: str | None = None,
) -> ReleasePair:
    """Select explicit, latest-published, local, or prospective release pairs.

    Publication chronology and numeric version order are distinct, explicit
    policies. A published package compares with its predecessor in that order.
    A prospective package must be newer than the selected latest release.
    Only current-vs-latest permits the same release label on both sources.
    """
    package_tag = normalize_tag(package_tag)
    if mode not in {"explicit", "published-latest", "infer-release", "current-vs-latest"}:
        raise ValueError(f"unknown release pair mode: {mode}")
    if order not in {"published", "version"}:
        raise ValueError("release order must be published or version")
    if mode == "explicit":
        if current is None or baseline is None:
            raise ValueError("explicit comparison requires both current and baseline tags")
        pair = ReleasePair(current, baseline)
    else:
        if current is not None or baseline is not None:
            raise ValueError(f"explicit tags cannot be combined with {mode}")
        if any(item.published_at.tzinfo is None for item in releases):
            raise ValueError("release timestamps must have a timezone")
        ordered = sorted(
            releases, key=lambda item: (item.published_at, _tag_version(item.tag)) if order == "published" else _tag_version(item.tag), reverse=True
        )
        tags = [normalize_tag(item.tag) for item in ordered]
        if len(tags) != len(set(tags)):
            raise ValueError("duplicate release tags")
        if not tags:
            raise ValueError("a published stable release is required")
        if mode == "published-latest":
            if len(tags) < 2:
                raise ValueError("at least two published stable releases are required")
            pair = ReleasePair(tags[0], tags[1])
        elif mode == "current-vs-latest":
            pair = ReleasePair(package_tag, tags[0])
        elif package_tag in tags:
            index = tags.index(package_tag)
            if index + 1 == len(tags):
                raise ValueError(f"published release {package_tag} has no previous stable release")
            pair = ReleasePair(package_tag, tags[index + 1])
        else:
            if _tag_version(package_tag) <= _tag_version(tags[0]):
                raise ValueError(f"unpublished package {package_tag} must be newer than {tags[0]}")
            pair = ReleasePair(package_tag, tags[0])
    if pair.current == pair.baseline and mode != "current-vs-latest":
        raise ValueError("current and baseline releases must differ")
    return pair

"""Common stable GitHub release discovery and transactional text publication."""

import json
import re
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from research_repo_tools.files import replace_many
from research_repo_tools.process import run_safe_command

TAG = re.compile(r"v?(?P<major>0|[1-9][0-9]*)\.(?P<minor>0|[1-9][0-9]*)\.(?P<patch>0|[1-9][0-9]*)")


@dataclass(frozen=True)
class PublishedRelease:
    tag: str
    published_at: datetime


def normalize_tag(tag: str) -> str:
    match = TAG.fullmatch(tag)
    if match is None:
        raise ValueError(f"release tag must use stable vX.Y.Z form: {tag!r}")
    return f"v{match['major']}.{match['minor']}.{match['patch']}"


def _tag_version(tag: str) -> tuple[int, ...]:
    return tuple(map(int, normalize_tag(tag)[1:].split(".")))

//! Memory/allocation measurement utilities.

#![forbid(unsafe_code)]

/// Memory measurement helper for allocation tracking in examples, tests, and benchmarks.
///
/// Available only with the `count-allocations` feature, which installs the allocation-counting
/// global allocator. Measurements cover the calling thread, not work spawned on other threads.
/// Enabling this feature adds the API without changing an existing function's return type.
///
/// # Arguments
///
/// * `f` - A closure to execute while measuring allocations
///
/// # Returns
///
/// Returns `(R, allocation_counter::AllocationInfo)`, containing the closure result and
/// allocation metrics. There is no no-op fallback that could be mistaken for a measurement.
///
/// # Panics
///
/// Panics if `f` panics. The internal `expect()` call is used because a
/// normally returning closure is guaranteed to set the result. The profiler also panics
/// when its supported nesting limit of 64 measurements is exceeded.
///
/// # Examples
///
/// ```rust
/// use delaunay::prelude::tds::measure_with_result;
///
/// let (result, alloc_info) = measure_with_result(|| {
///     vec![1, 2, 3, 4, 5]
/// });
/// assert_eq!(result, vec![1, 2, 3, 4, 5]);
///
/// assert!(alloc_info.bytes_total > 0);
/// ```
#[cfg_attr(docsrs, doc(cfg(feature = "count-allocations")))]
pub fn measure_with_result<F, R>(f: F) -> (R, allocation_counter::AllocationInfo)
where
    F: FnOnce() -> R,
{
    let mut result: Option<R> = None;
    let info = allocation_counter::measure(|| {
        result = Some(f());
    });
    (result.expect("Closure should have set result"), info)
}

    #[cfg(feature = "count-allocations")]
    pub mod measurement;
    #[cfg(feature = "count-allocations")]
    pub use measurement::*;
#[cfg(feature = "count-allocations")]
#[cfg_attr(docsrs, doc(cfg(feature = "count-allocations")))]
pub use crate::core::util::measure_with_result;
#[cfg(feature = "count-allocations")]
#[cfg_attr(docsrs, doc(cfg(feature = "count-allocations")))]
pub use crate::core::util::measure_with_result;
